<script setup>
import { ref, onMounted, watch, onUnmounted, computed } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import singleCard from '../../components/cards/singleCard.vue'
import singlePage from '../../components/detail/singlePage.vue'
import { getSongGroups, getSongKeys, getSongDetail } from '../../api/infos.js'

const router = useRouter()
const route = useRoute()

const singleList = ref([])
const songNameList = ref([])
const songInfo = ref({})
const currentSong = ref('')
const errorMsg = ref('')
const infoErrorMsg = ref('')

const goToTable = (tableName) => {
  router.push({ 
    name: 'singleMain',
    params: { 
      songName: tableName
    }
  })
}

const validateSongExist = (songName) => {
  if (!songName || !songNameList.value.length) return false
  return songNameList.value.includes(songName)
}

const fetchSongInfo = async (songName) => {
  if (!songName) {
    songInfo.value = {}
    infoErrorMsg.value = ''
    return
  }
  
  infoErrorMsg.value = ''
  try {
    const infoData = await getSongDetail(songName)
    songInfo.value = infoData || {}
  } catch (error) {
    console.error('获取歌曲详情失败：', error)
    infoErrorMsg.value = '获取歌曲详情失败，请重试'
    songInfo.value = {}
  }
}

const clearInvalidSongParam = async () => {
  const songName = route.params.songName
  if (songName && !validateSongExist(songName)) {
    await router.push({
      name: 'singleMain',
      params: {},
      query: route.query,
      replace: true
    })
  } else if (songName) {
    currentSong.value = songName
    await fetchSongInfo(songName)
  }
}

onMounted(async () => {
  try {
    const [singleData, songListData] = await Promise.all([
      getSongGroups(),
      getSongKeys()
    ])
    
    singleList.value = singleData || []
    songNameList.value = songListData || []
    errorMsg.value = ''
    
    await clearInvalidSongParam()
  } catch (error) {
    console.error('数据加载失败：', error)
    errorMsg.value = '曲目列表加载失败，请刷新重试'
  }
})

watch(() => route.params.songName, async (newSongName) => {
  if (songNameList.value.length === 0) return
  
  if (newSongName && !validateSongExist(newSongName)) {
    await router.push({
      name: 'singleMain',
      params: {},
      query: route.query,
      replace: true
    })
    songInfo.value = {}
  } else {
    currentSong.value = newSongName || ''
    await fetchSongInfo(newSongName)
  }
}, { immediate: true })

const props = defineProps({
  columns: {
    type: Number,
    default: 6
  },
  gap: {
    type: Number,
    default: 0.20
  },
})

const getGridStyle = () => {
  return {
    '--column-count': props.columns,
    '--gap-rem': `${props.gap}rem`
  }
}

const sortedCardList = computed(() => {
  if (!singleList.value) return []
  const entries = Object.entries(singleList.value)
  const sortedEntries = entries.sort((a, b) => {
    const numA = Number(a[0])
    const numB = Number(b[0])
    return numB - numA
  })
  return sortedEntries.map(([key, value]) => ({ key, value }))
})
</script>

<template>
  <div class="table-container">
    <div v-if="singleList" class="table-card-list">
      <div class="card-container" v-if="!currentSong">
        <div 
          v-for="({ key: groupKey, value: cardGroup }, index) in sortedCardList" 
          :key="groupKey" 
          class="card-group"
        >
          <div class="group-title">{{ groupKey }}</div>
          <div class="card-grid" :style="getGridStyle()">
            <singleCard 
              v-for="(item, idx) in cardGroup" 
              :key="idx"
              :chart-info="item" 
              @click="goToTable(item[0])"
              :class="{ active: item[0] === currentSong }"
            />
          </div>
        </div>
      </div>
      
      <div v-if="currentSong" class="current-song-info">
        <div v-if="Object.keys(songInfo).length">
          <singlePage :dict="songInfo" />
        </div>
      </div>
    </div>
  </div>
</template>

<style scoped>
.table-container {
  width: 100%;
}

.card-container {
  width: 100%;
  box-sizing: border-box;
}
.card-group {
  width: 100%;
  margin-bottom: 0.24rem;
  box-sizing: border-box;
}
.group-title {
  height: 0.3rem;
  line-height: 0.3rem;
  background-color: var(--color-bg-sub);
  color: var(--color-text);
  padding: 0 0.16rem;
  font-size: 0.16rem;
  font-weight: 600;
  margin-bottom: 0.08rem;
  text-align: center;
  user-select: none;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(var(--column-count), 1fr);
  gap: var(--gap-rem);
  width: 100%;
  user-select: none;
}

.card-grid > * {
  width: 100%;
  box-sizing: border-box;
}

.current-song-info {
  margin-top: 0.4rem;
  padding: 0.2rem;
  text-align: center;
  color: var(--color-text);
}

:deep(.active) {
  background-color: var(--color-primary);
  color: #fff;
}
</style>