/**
 * /files/infos/infos.json（约 790 KB）的全部取数逻辑。
 *
 * 曲目列表、定数列表、B30、联机模拟、选曲组件、其它列表都来自这一份文件，
 * 现在它们共用同一次网络请求：谁先要谁触发下载，后面的调用直接拿缓存。
 */
import { loadJson } from './jsonCache.js'
import { NET, difColor, illLowPath, illPath } from './common.js'

export const INFOS_PATH = `${NET}/files/infos/infos.json`

/** 原始数据（缓存共享，调用方只读） */
export function loadInfos() {
  return loadJson(INFOS_PATH)
}

const OTHER_CHAPTER_KEY = 'Other 其它曲目'

/** 曲目列表页：按章节分组的卡片数据 */
export async function getSongGroups() {
  try {
    const jsonData = await loadInfos()
    const chapterGroup = {}

    for (const [levelId, levelInfo] of Object.entries(jsonData)) {
      if (!levelId || !levelInfo.name) continue

      let chapterKey
      if (levelInfo.display) {
        chapterKey = levelInfo.chapter || OTHER_CHAPTER_KEY
      } else {
        chapterKey = OTHER_CHAPTER_KEY
      }

      if (!chapterGroup[chapterKey]) {
        chapterGroup[chapterKey] = []
      }
      chapterGroup[chapterKey].push([levelId, chapterKey, illLowPath(levelId)])
    }

    return chapterGroup
  } catch (error) {
    console.error('获取数据失败：', error)
    console.error('实际请求的JSON文件路径：', INFOS_PATH)
    return {}
  }
}

/** 全部曲目键名（用于校验 URL 上的曲名是否存在） */
export async function getSongKeys() {
  try {
    const jsonData = await loadInfos()
    return Object.keys(jsonData)
  } catch (error) {
    console.error('获取数据失败：', error)
    console.error('实际请求的JSON文件路径：', INFOS_PATH)
    return []
  }
}

/** 单曲详情 */
export async function getSongDetail(songId) {
  try {
    const jsonData = await loadInfos()

    if (!Object.prototype.hasOwnProperty.call(jsonData, songId)) {
      console.warn(`未找到键名为 "${songId}" 的数据`)
      return null
    }

    const originalData = jsonData[songId]
    const detail =
      typeof originalData === 'object' && originalData !== null
        ? { ...originalData }
        : { value: originalData }

    return { ...detail, illAssets: illPath(songId) }
  } catch (error) {
    console.error('获取数据失败：', error)
    console.error('实际请求的JSON文件路径：', INFOS_PATH)
    return null
  }
}

/** 其它列表页：按 fieldMap 取字段拼表头与数据行 */
export async function getInfoTable(fieldMap = {}) {
  const buildHeader = () => {
    const header = {}
    Object.entries(fieldMap).forEach(([label, key]) => {
      header[label] = key
    })
    return header
  }

  try {
    const jsonData = await loadInfos()
    const dataRows = []

    for (const [, levelInfo] of Object.entries(jsonData)) {
      if (!levelInfo.name || !levelInfo.display) continue

      const row = {}
      Object.entries(fieldMap).forEach(([label, key]) => {
        const keyParts = key.split(':')
        let value = ''
        if (keyParts.length === 1) {
          value = levelInfo[keyParts[0]] ?? ''
        } else {
          const [category, prop] = keyParts
          value = levelInfo[category]?.[prop] ?? ''
        }
        row[label] = value
      })
      if (Object.keys(row).length > 0) {
        dataRows.push(row)
      }
    }

    return [buildHeader(), ...dataRows]
  } catch (error) {
    console.error('获取数据失败：', error)
    console.error('实际请求的JSON文件路径：', INFOS_PATH)
    return [buildHeader()]
  }
}

/** 联机模拟：把 "曲名+难度" 文本解析成谱面列表 */
export async function searchCharts(inputText) {
  try {
    const infosData = await loadInfos()
    const text = inputText?.trim() || ''
    if (!text) return []

    const chartStrings = text.split(/\s+/)
    const result = []

    for (const str of chartStrings) {
      if (!str) continue

      const difficulty = str.slice(-2)
      const chartId = str.slice(0, -2)
      const chartInfo = infosData[chartId]
      if (!chartInfo) continue

      result.push({
        id: chartId,
        name: chartInfo.name || 'UNKNOWN',
        dif: chartInfo[difficulty]?.dif || '?',
        color: difColor(difficulty),
        difficulty: difficulty,
        imgPath: illLowPath(chartId),
        score: 0
      })
    }

    return result
  } catch (error) {
    console.error('获取链接列表失败：', error)
    return []
  }
}
